import{_ as n,o,c as i,a3 as r}from"./chunks/framework.DX_KL3e0.js";const a="/help/screenshots/quan-tri/cau-hinh-ticket.png",p=JSON.parse('{"title":"Cấu hình Ticket","description":"","frontmatter":{},"headers":[],"relativePath":"quan-tri/cau-hinh-ticket.md","filePath":"quan-tri/cau-hinh-ticket.md","lastUpdated":1781595364000}'),h={name:"quan-tri/cau-hinh-ticket.md"};function c(s,t,g,e,d,l){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="cau-hinh-ticket" tabindex="-1">Cấu hình Ticket <a class="header-anchor" href="#cau-hinh-ticket" aria-label="Permalink to &quot;Cấu hình Ticket&quot;">​</a></h1><p>Trang <strong>Cấu Hình Ticket</strong> định nghĩa <strong>Loại Yêu Cầu</strong> và <strong>Danh Mục</strong> (kèm trường động) cho hệ thống tác vụ/ticket.</p><div class="warning custom-block"><p class="custom-block-title">Chỉ Super Admin</p><p>Lối vào <code>/tickets/admin/config</code> <strong>chỉ hiển thị với Super Admin</strong>. Admin <strong>không</strong> thấy mục này. Người không phải Super Admin chỉ xem được, không chỉnh sửa.</p></div><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tickets/admin/config</code> (vào từ <strong>Quản Lý Ticket</strong> › nút cấu hình).</li><li><strong>Ai dùng được:</strong> <strong>chỉ Super Admin</strong>.</li><li><strong>Hai tab:</strong> Loại Yêu Cầu · Danh Mục.</li></ul></div><h2 id="giao-dien" tabindex="-1">Giao diện <a class="header-anchor" href="#giao-dien" aria-label="Permalink to &quot;Giao diện&quot;">​</a></h2><p><img src="'+a+'" alt="Trang Cấu hình Ticket"></p><p>Trang gồm nút <strong>Quay lại Quản Lý Ticket</strong> (←) và hai tab.</p><h2 id="tab-loai-yeu-cau" tabindex="-1">Tab Loại Yêu Cầu <a class="header-anchor" href="#tab-loai-yeu-cau" aria-label="Permalink to &quot;Tab Loại Yêu Cầu&quot;">​</a></h2><p>Quản lý danh sách <strong>loại yêu cầu</strong> dùng để phân nhóm ticket.</p><ol><li>Mở tab <strong>Loại Yêu Cầu</strong>.</li><li>Nhấn <strong>Thêm</strong> để tạo loại mới: nhập <strong>mã (code)</strong>, <strong>tên</strong>, thứ tự sắp xếp.</li><li>Bật/tắt <strong>trạng thái hoạt động</strong>, <strong>sửa</strong> hoặc <strong>lưu trữ/xóa</strong> loại đã có.</li></ol><h2 id="tab-danh-muc" tabindex="-1">Tab Danh Mục <a class="header-anchor" href="#tab-danh-muc" aria-label="Permalink to &quot;Tab Danh Mục&quot;">​</a></h2><p>Quản lý <strong>danh mục</strong> ticket, có thể lồng cấp (cha–con) và gắn <strong>trường động (custom fields)</strong>.</p><ol><li>Mở tab <strong>Danh Mục</strong>.</li><li>Nhấn <strong>Thêm</strong> để tạo: chọn <strong>danh mục cha</strong> (nếu có), nhập <strong>tên</strong>, gán <strong>loại yêu cầu</strong> liên quan, <strong>thẻ đơn vị mặc định</strong>.</li><li>Thêm <strong>trường động</strong> cho danh mục — mỗi trường có <strong>nhãn</strong> và <strong>kiểu</strong>:</li></ol><table tabindex="0"><thead><tr><th>Kiểu trường</th><th>Dùng cho</th></tr></thead><tbody><tr><td>Văn bản ngắn</td><td>Thông tin một dòng</td></tr><tr><td>Văn bản dài</td><td>Mô tả nhiều dòng</td></tr><tr><td>Số</td><td>Giá trị số</td></tr><tr><td>Ngày</td><td>Chọn ngày</td></tr><tr><td>Chọn (danh sách)</td><td>Lựa chọn từ danh sách định sẵn</td></tr></tbody></table><ol start="4"><li>Đặt trường <strong>bắt buộc</strong> nếu cần, sắp <strong>thứ tự</strong>, rồi <strong>Lưu</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Hướng tới ERP</p><p>Hệ thống tác vụ/ticket được thiết kế để xử lý công việc nội bộ toàn doanh nghiệp, không chỉ riêng tài sản. Loại yêu cầu &amp; danh mục cấu hình ở đây áp dụng cho toàn bộ luồng tác vụ.</p></div><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tickets.html">Ticket Hỗ trợ</a> · <a href="/help/vai-tro/super-admin.html">Super Admin</a></p>',18)])])}const m=n(h,[["render",c]]);export{p as __pageData,m as default};
